// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, uniqueSuffix } from '@skyramp/skyramp';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:2368");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Ghost " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const endpoint2PostRequestBody: string = `{
        "members": [
            {
                "email": "skyramp_growth@example.com",
                "name": "Skyramp Growth Member"
            }
        ]
    }`;

    // Execute Request
    const endpoint2PostResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/admin/members/",
        method: "POST",
        body: endpoint2PostRequestBody,
        headers: headers,
        dataOverride: {"members.0.email": uniqueSuffix("skyramp_growth@example.com")}
    });

    // Generated Assertions
    expect(endpoint2PostResponse.statusCode, 'status code').toBe(201);
    expect(getValue(endpoint2PostResponse, "members.0.name"), 'name').toBe("Skyramp Growth Member");
    expect(getValue(endpoint2PostResponse, "members.0.email"), 'email').toContain("@example.com");
    expect(getValue(endpoint2PostResponse, "members.0.id"), 'id').toMatch(/^[0-9a-f]{24}$/i);
    expect(getValue(endpoint2PostResponse, "members.0.uuid"), 'uuid').toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i);
    expect(getValue(endpoint2PostResponse, "members.0.created_at"), 'created_at').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(getValue(endpoint2PostResponse, "members.0.subscribed"), 'subscribed').toBe(true);
    expect(getValue(endpoint2PostResponse, "members.0.labels.0") ?? null, 'labels is empty').toBeNull();
    expect(getValue(endpoint2PostResponse, "members.0.subscriptions.0") ?? null, 'subscriptions is empty').toBeNull();
    expect(getValue(endpoint2PostResponse, "members.1.id") ?? null, 'exactly one member created').toBeNull();

    // Execute Request
    const endpoint1GetResponse = await client.sendRequest({
        url: URL_localhost,
        path: "/ghost/api/admin/analytics/member-growth/",
        method: "GET",
        headers: headers
    });

    // Generated Assertions
    expect(endpoint1GetResponse.statusCode, 'status code').toBe(200);

    const growthStartDate: string = getValue(endpoint1GetResponse, "start_date");
    const growthEndDate: string = getValue(endpoint1GetResponse, "end_date");
    expect(growthStartDate, 'start_date').toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(growthEndDate, 'end_date').toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(
        Math.round((Date.parse(`${growthEndDate}T00:00:00Z`) - Date.parse(`${growthStartDate}T00:00:00Z`)) / 86400000),
        'default window spans 30 days'
    ).toBe(30);

    const growthDates: string[] = [];
    const growthCounts: number[] = [];
    for (let bucketIndex = 0; bucketIndex < 400; bucketIndex++) {
        const bucketDate = getValue(endpoint1GetResponse, `data.${bucketIndex}.date`) ?? null;
        if (bucketDate === null) {
            break;
        }
        growthDates.push(bucketDate);
        growthCounts.push(getValue(endpoint1GetResponse, `data.${bucketIndex}.count`));
    }

    expect(growthDates.length, 'data length').toBeGreaterThanOrEqual(1);
    expect(getValue(endpoint1GetResponse, "data.0.date"), 'data.0.date').toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(getValue(endpoint1GetResponse, "data.0.count"), 'data.0.count').toBeGreaterThanOrEqual(1);

    for (let bucketIndex = 0; bucketIndex < growthDates.length; bucketIndex++) {
        const bucketDate = growthDates[bucketIndex];
        expect(bucketDate, `bucket date format for ${bucketDate}`).toMatch(/^\d{4}-\d{2}-\d{2}$/);
        expect(
            bucketDate >= growthStartDate && bucketDate <= growthEndDate,
            `bucket ${bucketDate} falls inside requested window ${growthStartDate}..${growthEndDate}`
        ).toBe(true);
        expect(growthCounts[bucketIndex], `count for bucket ${bucketDate}`).toBeGreaterThanOrEqual(1);
    }

    const growthTotal = growthCounts.reduce((sum: number, bucketCount: number) => sum + bucketCount, 0);
    expect(growthTotal, 'summed member growth includes the member created above').toBeGreaterThanOrEqual(1);

    const createdMemberDate: string = getValue(endpoint2PostResponse, "members.0.created_at").slice(0, 10);
    expect(
        growthDates.includes(createdMemberDate),
        `series contains a bucket for the created member's date ${createdMemberDate}`
    ).toBe(true);
});
